<?php
use App\Models\Cita;
$base='/pacientes/'.(int)$paciente['id'].'/historial-citas';
$filtros=array_intersect_key($f,array_flip(['desde','hasta','estado','medico_id','especialidad_id','periodo','pagina']));
?>
<section class="page-heading"><p class="eyebrow"><?= e($paciente['codigo']) ?> · CU20</p><h1>Historial de citas</h1><p class="lead"><?= e($paciente['nombres'].' '.$paciente['apellidos']) ?></p></section>
<p class="notice" role="status">Historial administrativo, no historia clínica. Se muestran únicamente las citas autorizadas para tu cuenta. America/La_Paz.</p>
<nav class="historial-accesos" aria-label="Consulta rápida"><a class="button button-secondary" href="<?= e($base) ?>">Mostrar todas</a><a class="text-link" href="<?= e($base) ?>?periodo=proximas">Mostrar futuras</a><a class="text-link" href="<?= e($base) ?>?periodo=historicas">Mostrar anteriores</a><a class="text-link" href="<?= e($base) ?>?estado=cancelada">Mostrar canceladas</a><a class="text-link" href="/historial-citas">Buscar otro paciente</a></nav>
<form class="panel historial-panel historial-filtros" method="get" action="<?= e($base) ?>" data-historial-filtros>
<div class="field-group"><label for="historial-desde">Desde</label><input id="historial-desde" name="desde" type="date" value="<?= e($f['desde']) ?>"></div><div class="field-group"><label for="historial-hasta">Hasta, inclusive</label><input id="historial-hasta" name="hasta" type="date" value="<?= e($f['hasta']) ?>"></div>
<div class="field-group"><label for="historial-estado">Estado</label><select id="historial-estado" name="estado"><option value="">Todos los estados</option><?php foreach(Cita::ESTADOS as $valor=>$label): ?><option value="<?= e($valor) ?>" <?= $f['estado']===$valor?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div>
<?php if($seleccionarMedico): ?><div class="field-group"><label for="historial-medico">Médico</label><select id="historial-medico" name="medico_id"><option value="">Todos los de este paciente</option><?php foreach($medicos as $m): ?><option value="<?= (int)$m['id'] ?>" <?= $f['medico_id']===(string)$m['id']?'selected':'' ?>><?= e($m['apellidos'].', '.$m['nombres']) ?></option><?php endforeach; ?></select></div><?php endif; ?>
<div class="field-group"><label for="historial-especialidad">Especialidad</label><select id="historial-especialidad" name="especialidad_id"><option value="">Todas</option><?php foreach($especialidades as $e): ?><option value="<?= (int)$e['id'] ?>" <?= $f['especialidad_id']===(string)$e['id']?'selected':'' ?>><?= e($e['nombre']) ?></option><?php endforeach; ?></select></div>
<div class="field-group"><label for="historial-periodo">Período según inicio de cita</label><select id="historial-periodo" name="periodo"><?php foreach(['todas'=>'Todas','proximas'=>'Futuras','historicas'=>'Anteriores'] as $v=>$label): ?><option value="<?= e($v) ?>" <?= $f['periodo']===$v?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div>
<button class="button" type="submit">Aplicar filtros</button></form>
<section class="panel table-panel historial-panel"><h2><?= (int)$resultado['total'] ?> citas visibles con estos filtros</h2>
<?php if(!$resultado['filas']): ?><p class="empty-state" role="status">No hay citas visibles para este paciente con los filtros seleccionados.</p><?php else: ?>
<div class="table-scroll"><table><thead><tr><th>Código</th><th>Horario local</th><th>Duración</th><th>Médico</th><th>Especialidad</th><th>Estado</th><th>Consulta</th></tr></thead><tbody>
<?php foreach($resultado['filas'] as $c): ?><tr data-historial-cita="<?= (int)$c['id'] ?>"><td data-label="Código"><?= e($c['codigo']) ?></td><td data-label="Horario local"><span><?= e($c['inicio_local']) ?> → <?= e($c['fin_local']) ?></span></td><td data-label="Duración"><?= (int)$c['duracion_minutos'] ?> min</td><td data-label="Médico"><?= e($c['medico_apellidos'].', '.$c['medico_nombres']) ?></td><td data-label="Especialidad"><?= e($c['especialidad']??'Sin registrar') ?></td><td data-label="Estado"><span class="status-pill appointment-<?= e($c['estado']) ?>"><?= e(Cita::ESTADOS[$c['estado']]) ?></span></td><td data-label="Consulta"><div class="historial-enlaces"><a class="text-link" href="/citas/<?= (int)$c['id'] ?>">Ver detalle CU14</a><?php if($c['eventos']>0): ?><a class="text-link" href="<?= e($base) ?>/<?= (int)$c['id'] ?>/eventos">Ver eventos (<?= (int)$c['eventos'] ?>)</a><?php else: ?><span>Sin eventos registrados</span><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div>
<?php endif; ?>
<nav class="pagination" aria-label="Páginas del historial"><?php if($resultado['pagina']>1): ?><a class="text-link" data-historial-anterior href="?<?= e(http_build_query(array_replace($filtros,['pagina'=>$resultado['pagina']-1]))) ?>">← Anterior</a><?php endif; ?><span>Página <?= $resultado['pagina'] ?> de <?= $resultado['paginas'] ?></span><?php if($resultado['pagina']<$resultado['paginas']): ?><a class="text-link" data-historial-siguiente href="?<?= e(http_build_query(array_replace($filtros,['pagina'=>$resultado['pagina']+1]))) ?>">Siguiente →</a><?php endif; ?></nav></section>
